/* Pesticide Shop ERP - local-first starter implementation.
   All records remain in this browser's IndexedDB. Export backups regularly. */
const DB_NAME="PesticideShopERP", DB_VERSION=2;
const TABLES=["companies","products","customers","sales","payments","purchases","suppliers","expenses","movements","settings","users"];
let db, page="dashboard", currentUser={name:"Owner",role:"Owner"}, editing=null;
window.erpSetUser=(user,role)=>{currentUser={name:user?.email||"Owner",role:role||"Owner"};const n=document.getElementById("userName"),r=document.getElementById("userRole");if(n)n.textContent=currentUser.name;if(r)r.textContent=currentUser.role;document.querySelectorAll(".nav-item").forEach(b=>{b.hidden=currentUser.role==="assistant"&&["companies","purchases","expenses","reports","settings"].includes(b.dataset.page)})};
const $=s=>document.querySelector(s), money=n=>"Rs. "+Number(n||0).toLocaleString("en-PK",{maximumFractionDigits:2});
const today=()=>new Date().toISOString().slice(0,10);
const uid=()=>crypto.randomUUID?crypto.randomUUID():String(Date.now())+Math.random().toString(16).slice(2);
function esc(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function qrSvg(value,size=144){
 const qr=window.GSCQRCode?.create(value);if(!qr)return '<span>QR unavailable</span>';
 const n=qr.getModuleCount(),quiet=4,cell=4,dim=(n+quiet*2)*cell;let path='';
 for(let y=0;y<n;y++)for(let x=0;x<n;x++)if(qr.modules[y][x])path+=`M${(x+quiet)*cell} ${(y+quiet)*cell}h${cell}v${cell}h-${cell}z`;
 return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 ${dim} ${dim}" role="img" aria-label="QR code"><rect width="100%" height="100%" fill="#fff"/><path d="${path}" fill="#102f25"/></svg>`;
}
const CODE39={"0":"nnnwwnwnn","1":"wnnwnnnnw","2":"nnwwnnnnw","3":"wnwwnnnnn","4":"nnnwwnnnw","5":"wnnwwnnnn","6":"nnwwwnnnn","7":"nnnwnnwnw","8":"wnnwnnwnn","9":"nnwwnnwnn","A":"wnnnnwnnw","B":"nnwnnwnnw","C":"wnwnnwnnn","D":"nnnnwwnnw","E":"wnnnwwnnn","F":"nnwnwwnnn","G":"nnnnnwwnw","H":"wnnnnwwnn","I":"nnwnnwwnn","J":"nnnnwwwnn","K":"wnnnnnnww","L":"nnwnnnnww","M":"wnwnnnnwn","N":"nnnnwnnww","O":"wnnnwnnwn","P":"nnwnwnnwn","Q":"nnnnnnnww","R":"wnnnnnnwn","S":"nnwnnnnwn","T":"nnnnwnnwn","U":"wwnnnnnnw","V":"nwwnnnnnw","W":"wwwnnnnnn","X":"nwnnwnnnw","Y":"wwn nwnnnn".replaceAll(' ',''),"Z":"nwwnwnnnn","-":"nwnnnnwnw",".":"wwnnnwnnn"," ":"nwwnnnwnn","$":"nwnwnwnnn","/":"nwnwnnnwn","+":"nwnnnwnwn","%":"nnnwnwnwn","*":"nwnnwnwnn"};
function barcodeSvg(value){const text=String(value||'').toUpperCase().replace(/[^0-9A-Z. $/+%-]/g,'-').slice(0,32)||'GSC';const full='*'+text+'*';let x=10,rects='';for(const ch of full){const pat=CODE39[ch]||CODE39['-'];for(let i=0;i<9;i++){const w=pat[i]==='w'?3:1;if(i%2===0)rects+=`<rect x="${x}" y="4" width="${w}" height="48"/>`;x+=w}x+=1}return `<svg xmlns="http://www.w3.org/2000/svg" width="${Math.max(220,x+10)}" height="76" viewBox="0 0 ${x+10} 76" role="img" aria-label="Barcode"><rect width="100%" height="100%" fill="white"/><g fill="#111">${rects}</g><text x="50%" y="68" text-anchor="middle" font-family="Arial" font-size="11">${esc(text)}</text></svg>`}
function tryOpenInvoiceCode(code){try{const u=new URL(code);const invoice=u.searchParams.get("invoice");if(invoice){viewInvoice(invoice);return true}}catch{}return false}
function applyScannedCode(code,targetId){if(tryOpenInvoiceCode(code))return;const input=document.getElementById(targetId);if(!input)return;input.value=code;input.dispatchEvent(new Event('input',{bubbles:true}));if(['saleBarcode','fPurchaseBarcode'].includes(targetId))input.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',bubbles:true}));}
async function startBarcodeCamera(targetId){
 if(!navigator.mediaDevices?.getUserMedia||!('BarcodeDetector'in window)){toast('Camera barcode scanning is not supported in this browser. Use a USB/Bluetooth scanner or type the barcode.');return}
 let stream=null,active=true;const root=$('#modalRoot');root.innerHTML=`<div class="modal-backdrop"><div class="modal camera-modal"><h2>Scan product barcode</h2><video id="barcodeVideo" autoplay muted playsinline></video><p class="muted">Barcode ko camera ke samne seedha rakhein.</p><div class="modal-actions"><button class="btn btn-light" id="stopBarcodeCamera">Cancel</button></div></div></div>`;
 const stop=()=>{active=false;if(stream)stream.getTracks().forEach(t=>t.stop());root.innerHTML=''};$('#stopBarcodeCamera').onclick=stop;
 try{const supported=await BarcodeDetector.getSupportedFormats();const formats=['qr_code','code_128','code_39','ean_13','ean_8','upc_a','upc_e','codabar','itf'].filter(x=>supported.includes(x));if(!formats.length)throw new Error('No supported barcode formats');const detector=new BarcodeDetector({formats});stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});const video=$('#barcodeVideo');video.srcObject=stream;await video.play();const scan=async()=>{if(!active)return;try{const codes=await detector.detect(video);if(codes.length){const value=codes[0].rawValue;stop();applyScannedCode(value,targetId);return}}catch{}setTimeout(scan,250)};scan()}catch(e){stop();toast('Camera could not start. Check camera permission and HTTPS.')}
}
function toast(s){const el=document.createElement("div");el.className="toast";el.textContent=s;$("#toastRoot").append(el);setTimeout(()=>el.remove(),3000)}
function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB_NAME,DB_VERSION);req.onupgradeneeded=()=>{const d=req.result;TABLES.forEach(t=>{if(!d.objectStoreNames.contains(t))d.createObjectStore(t,{keyPath:"id"})});if(!d.objectStoreNames.contains("sync_outbox"))d.createObjectStore("sync_outbox",{keyPath:"id"})};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
function all(table){return new Promise((res,rej)=>{const r=db.transaction(table).objectStore(table).getAll();r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error)})}
function get(table,id){return new Promise((res,rej)=>{const r=db.transaction(table).objectStore(table).get(id);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function queueLocalChange(table,obj,deleted=false){if(window.__cloudApplying||!db)return Promise.resolve();return new Promise((res,rej)=>{const tx=db.transaction("sync_outbox","readwrite");tx.objectStore("sync_outbox").put({id:table+":"+obj.id,table,recordId:obj.id,payload:deleted?null:obj,deleted,changedAt:new Date().toISOString()});tx.oncomplete=()=>{window.dispatchEvent(new Event("erp:local-change"));res()};tx.onerror=()=>rej(tx.error)})}
function put(table,obj){return new Promise((res,rej)=>{const tx=db.transaction(table,"readwrite");tx.objectStore(table).put(obj);tx.oncomplete=async()=>{try{await queueLocalChange(table,obj,false);res(obj)}catch(e){rej(e)}};tx.onerror=()=>rej(tx.error)})}
function del(table,id){return new Promise(async(res,rej)=>{try{const old=await get(table,id);const tx=db.transaction(table,"readwrite");tx.objectStore(table).delete(id);tx.oncomplete=async()=>{try{if(old)await queueLocalChange(table,old,true);res()}catch(e){rej(e)}};tx.onerror=()=>rej(tx.error)}catch(e){rej(e)}})}
async function seed(){/* No demo records are inserted. Shop settings are created when the owner saves them. */}
function pageTitle(p){return ({cloud:"Cloud sync & team",dashboard:"Dashboard",sales:"New Sale / POS",customers:"Customers & Credit",products:"Products & Stock",companies:"Companies",purchases:"Purchases",payments:"Payments",expenses:"Expenses",reports:"Reports",settings:"Settings & Backup"})[p]||p}
function setPage(p){page=p;document.querySelectorAll(".nav-item").forEach(b=>b.classList.toggle("active",b.dataset.page===p));$("#pageTitle").textContent=pageTitle(p);$("#sidebar")?.classList.remove("open");render()}
function fmtDate(d){return d?new Date(d).toLocaleDateString("en-PK"):"—"}
function table(headers,rows,empty="No records yet."){return `<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join("")}</tr></thead><tbody>${rows.length?rows.join(""):`<tr><td colspan="${headers.length}"><div class="empty"><b>${empty}</b>Add your first record to get started.</div></td></tr>`}</tbody></table></div>`}
function stat(label,value,note,icon){return `<div class="card"><span class="stat-icon">${icon}</span><div class="stat-label">${label}</div><div class="stat-value">${value}</div><div class="stat-note">${note||""}</div></div>`}
async function render(){
 const c=$("#content"); if(!c)return;
 if(page==="cloud")return cloudPage(c);
 if(page==="dashboard")return dashboard(c);
 if(page==="companies")return companiesPage(c);
 if(page==="products")return productsPage(c);
 if(page==="customers")return customersPage(c);
 if(page==="sales")return salesPage(c);
 if(page==="payments")return paymentsPage(c);
 if(page==="purchases")return purchasesPage(c);
 if(page==="expenses")return expensesPage(c);
 if(page==="reports")return reportsPage(c);
 if(page==="settings")return settingsPage(c);
}
async function dashboard(c){
 const [sales,customers,products,purchases,expenses]=await Promise.all(["sales","customers","products","purchases","expenses"].map(all));
 const month=today().slice(0,7), todays=sales.filter(x=>x.date===today()), monthly=sales.filter(x=>(x.date||"").startsWith(month));
 const total=s=>s.reduce((a,x)=>a+Number(x.total||0),0), received=payments=>payments.reduce((a,x)=>a+Number(x.amount||0),0);
 const pays=await all("payments"), outstanding=customers.reduce((a,x)=>a+Number(x.balance||0),0), stockValue=products.reduce((a,x)=>a+Number(x.stock||0)*Number(x.purchasePrice||0),0);
 const low=products.filter(x=>Number(x.stock||0)<=Number(x.minStock||0));
 const exp=products.filter(x=>x.expiryDate&&x.expiryDate<=new Date(Date.now()+90*86400000).toISOString().slice(0,10));
 c.innerHTML=`<div class="grid stats">${stat("Today's sales",money(total(todays)),"Invoices created today","↗")}${stat("Monthly sales",money(total(monthly)),"Current calendar month","▦")}${stat("Customer outstanding",money(outstanding),"Total customer balances","৳")}${stat("Payments received",money(received(pays.filter(x=>x.date===today()))),"Collected today","✓")}${stat("Inventory value",money(stockValue),"At recorded purchase cost","▤")}${stat("Products in catalogue",products.length,"Product / pack records","◫")}${stat("Low-stock products",low.length,"At or below minimum level","!")}${stat("Near-expiry products",exp.length,"Expiry within 90 days","⌛")}</div>
 <div class="grid two-col"><div class="card"><h2>Recent sales</h2><p class="muted">Latest saved invoices</p>${table(["Invoice","Customer","Date","Total","Due"],sales.slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).slice(0,6).map(s=>`<tr><td><b>${esc(s.invoiceNo)}</b></td><td>${esc(s.customerName)}</td><td>${fmtDate(s.date)}</td><td>${money(s.total)}</td><td>${money(s.due)}</td></tr>`))}</div><div class="card"><h2>Stock alerts</h2><p class="muted">Products needing attention</p>${table(["Product","Stock","Minimum"],low.slice(0,7).map(p=>`<tr><td>${esc(p.name)}</td><td><span class="pill red">${p.stock} ${esc(p.unit||"")}</span></td><td>${p.minStock||0}</td></tr>`))}<div class="section-head"><h2>Quick actions</h2></div><div class="quick-actions"><button class="btn btn-primary" data-go="sales">＋ New sale</button><button class="btn btn-light" data-go="customers">＋ Customer</button><button class="btn btn-light" data-go="products">＋ Product</button></div></div></div>`;
}
async function companiesPage(c){const rows=await all("companies");c.innerHTML=`<div class="section-head"><div><h2>Company directory</h2><p>Manage pesticide manufacturers and distributors.</p></div><button class="btn btn-primary" data-action="add-company">＋ Add company</button></div>${table(["Company","Representative","Phone","Address","Actions"],rows.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${esc(x.representative)}</td><td>${esc(x.phone)}</td><td>${esc(x.address)}</td><td><button class="btn btn-light btn-small" data-edit="company" data-id="${x.id}">Edit</button> <button class="btn btn-danger btn-small" data-delete="company" data-id="${x.id}">Delete</button></td></tr>`))}`}
async function productsPage(c){const [rows,companies]=await Promise.all([all("products"),all("companies")]);const q=window.productQuery||"";const filtered=rows.filter(x=>(x.name+" "+x.sku+" "+x.barcode+" "+x.brand).toLowerCase().includes(q.toLowerCase()));c.innerHTML=`<div class="section-head"><div><h2>Product catalogue & inventory</h2><p>Each pack size is tracked as a separate stock record.</p></div><button class="btn btn-primary" data-action="add-product">＋ Add product</button></div><div class="toolbar"><input class="input search" id="productSearch" placeholder="Search product, brand or scan barcode..." value="${esc(q)}"><button class="btn btn-light" id="productCameraScan">▣ Scan with camera</button><select class="select" id="companyFilter"><option value="">All companies</option>${companies.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join("")}</select></div>${table(["Product / SKU","Company","Category","Pack","Stock","Purchase","Retail","Expiry","Actions"],filtered.map(x=>{const co=companies.find(a=>a.id===x.companyId);return `<tr><td><b>${esc(x.name)}</b><div class="muted">${esc(x.sku||x.barcode||"")}</div></td><td>${esc(co?.name||"—")}</td><td>${esc(x.category)}</td><td>${esc(x.packSize)} ${esc(x.unit)}</td><td>${Number(x.stock||0)<=Number(x.minStock||0)?`<span class="pill red">${x.stock}</span>`:x.stock}</td><td>${money(x.purchasePrice)}</td><td>${money(x.retailPrice)}</td><td>${fmtDate(x.expiryDate)}</td><td><button class="btn btn-light btn-small" data-edit="product" data-id="${x.id}">Edit</button> <button class="btn btn-light btn-small" data-stock="${x.id}">Adjust</button> <button class="btn btn-light btn-small" data-barcode="${x.id}">Barcode</button> <button class="btn btn-light btn-small" data-buyers="${x.id}">Buyers</button></td></tr>`}))}`;
 $('#productCameraScan').onclick=()=>startBarcodeCamera('productSearch');
}
async function customersPage(c){const [rows,sales,pays]=await Promise.all([all("customers"),all("sales"),all("payments")]);const q=window.customerQuery||"";const filtered=rows.filter(x=>(x.name+" "+x.phone+" "+x.village).toLowerCase().includes(q.toLowerCase()));c.innerHTML=`<div class="section-head"><div><h2>Customer accounts</h2><p>Individual running balances and account statements.</p></div><button class="btn btn-primary" data-action="add-customer">＋ Add customer</button></div><div class="toolbar"><input class="input search" id="customerSearch" placeholder="Search name, mobile or village..." value="${esc(q)}"></div>${table(["Account","Customer","Mobile","Village","Credit limit","Outstanding","Actions"],filtered.map(x=>`<tr><td>${esc(x.accountNo||"—")}</td><td><b>${esc(x.name)}</b><div class="muted">${esc(x.type||"Customer")}</div></td><td>${esc(x.phone)}</td><td>${esc(x.village)}</td><td>${money(x.creditLimit)}</td><td><span class="${x.balance>0?"pill warn":"pill"}">${money(x.balance)}</span></td><td><button class="btn btn-light btn-small" data-ledger="${x.id}">Ledger</button> <button class="btn btn-light btn-small" data-customer-history="${x.id}">Products</button> <button class="btn btn-light btn-small" data-edit="customer" data-id="${x.id}">Edit</button></td></tr>`))}`}
async function salesPage(c){const [products,customers,sales]=await Promise.all([all("products"),all("customers"),all("sales")]);c.innerHTML=`<div class="grid two-col"><div class="card"><h2>Create invoice</h2><p class="muted">Select a customer and add products to the sale.</p><div class="form-grid" style="margin-top:16px"><div class="field full"><label>Customer</label><select class="select" id="saleCustomer"><option value="">Walk-in / Cash customer</option>${customers.map(x=>`<option value="${x.id}">${esc(x.name)} · Due ${money(x.balance)}</option>`).join("")}</select></div><div class="field full"><label>Scan barcode / SKU</label><div class="scan-row"><input class="input" id="saleBarcode" placeholder="Scan with handheld scanner or type code"><button class="btn btn-light" id="saleCameraScan">▣ Camera</button></div></div><div class="field full"><label>Product</label><select class="select" id="saleProduct"><option value="">Select product</option>${products.filter(x=>Number(x.stock)>0).map(x=>`<option value="${x.id}">${esc(x.name)} · ${esc(x.packSize)} ${esc(x.unit)} · Stock ${x.stock} · ${money(x.retailPrice)}</option>`).join("")}</select></div><div class="field"><label>Quantity</label><input class="input" type="number" min="0.01" step="0.01" id="saleQty" value="1"></div><div class="field"><label>Unit price (PKR)</label><input class="input" type="number" min="0" step=".01" id="salePrice"></div></div><button class="btn btn-light" style="margin-top:12px" id="addSaleLine">Add to invoice</button><div id="saleCart" style="margin-top:16px"><div class="empty">No products added yet.</div></div><div class="form-grid" style="margin-top:15px"><div class="field"><label>Discount (PKR)</label><input class="input" id="saleDiscount" type="number" min="0" value="0"></div><div class="field"><label>Amount received (PKR)</label><input class="input" id="salePaid" type="number" min="0" value="0"></div><div class="field"><label>Payment method</label><select class="select" id="saleMethod"><option>Cash</option><option>Bank transfer</option><option>JazzCash</option><option>Easypaisa</option><option>Cheque</option><option>Other</option></select></div><div class="field"><label>Due date (optional)</label><input class="input" id="saleDueDate" type="date"></div></div><div class="section-head"><h2 id="saleTotal">Total: Rs. 0</h2><button class="btn btn-primary" id="saveSale">Save invoice</button></div></div><div><div class="card"><h2>Recent invoices</h2><p class="muted">Saved sales records</p>${table(["Invoice","Customer","Total","Paid","Due","Details"],sales.slice().reverse().slice(0,10).map(s=>`<tr><td><b>${esc(s.invoiceNo)}</b></td><td>${esc(s.customerName)}</td><td>${money(s.total)}</td><td>${money(s.paid)}</td><td>${money(s.due)}</td><td><button class="btn btn-light btn-small" data-invoice="${esc(s.invoiceNo)}">View / QR</button></td></tr>`))}</div><div class="note" style="margin-top:14px">Stock is deducted and customer balance is updated when the invoice is saved. Completed invoices are retained as records; do not delete database entries manually.</div></div></div>`;
 window.saleCart=[];$("#saleCameraScan").onclick=()=>startBarcodeCamera("saleBarcode");$("#saleBarcode").onkeydown=async e=>{if(e.key!=="Enter")return;e.preventDefault();const raw=e.currentTarget.value.trim();if(tryOpenInvoiceCode(raw))return;const code=raw.toLowerCase();const found=(p=>String(p.sku||"").toLowerCase()===code||String(p.barcode||"").toLowerCase()===code);if(!found)return toast("No product found for this barcode.");if(Number(found.stock)<=0)return toast("This product is out of stock.");$("#saleProduct").value=found.id;$("#salePrice").value=found.retailPrice||0;$("#saleQty").focus();};$("#saleProduct").onchange=()=>{const p=products.find(x=>x.id===$("#saleProduct").value);$("#salePrice").value=p?.retailPrice||0};
 $("#addSaleLine").onclick=()=>{const p=products.find(x=>x.id===$("#saleProduct").value),qty=Number($("#saleQty").value),price=Number($("#salePrice").value);if(!p||qty<=0||price<0)return toast("Select a product and valid quantity.");if(qty>Number(p.stock))return toast("Not enough stock.");window.saleCart.push({productId:p.id,name:p.name,packSize:p.packSize,unit:p.unit,qty,price,companyId:p.companyId,cost:Number(p.purchasePrice||0)});drawCart()};
 $("#saleDiscount").oninput=drawCart;$("#salePaid").oninput=drawCart;
 function drawCart(){const cart=window.saleCart,total=cart.reduce((a,x)=>a+x.qty*x.price,0),discount=Math.max(0,Number($("#saleDiscount").value||0));$("#saleCart").innerHTML=cart.length?table(["Product","Qty","Rate","Amount",""],cart.map((x,i)=>`<tr><td>${esc(x.name)}<div class="muted">${esc(x.packSize)} ${esc(x.unit)}</div></td><td>${x.qty}</td><td>${money(x.price)}</td><td>${money(x.qty*x.price)}</td><td><button class="btn btn-danger btn-small" data-cartremove="${i}">×</button></td></tr>`)):`<div class="empty">No products added yet.</div>`;$("#saleTotal").textContent="Total: "+money(Math.max(0,total-discount));}
 $("#saveSale").onclick=async()=>{const cart=window.saleCart;if(!cart.length)return toast("Add at least one product.");const subtotal=cart.reduce((a,x)=>a+x.qty*x.price,0),discount=Math.max(0,Number($("#saleDiscount").value||0)),total=Math.max(0,subtotal-discount),paid=Math.max(0,Number($("#salePaid").value||0));if(discount>subtotal||paid>total)return toast("Check discount and received amount.");const customerId=$("#saleCustomer").value,customer=customerId?await get("customers",customerId):null;if(customer&&Number(customer.balance||0)+total-paid>Number(customer.creditLimit||Infinity)&&Number(customer.creditLimit||0)>0)return toast("This sale exceeds the customer's credit limit.");for(const line of cart){const p=await get("products",line.productId);if(!p||p.stock<line.qty)return toast("Stock changed. Refresh and try again.");}
 const invoiceNo="INV-"+today().replaceAll("-","")+"-"+String(Date.now()).slice(-5),sale={id:uid(),invoiceNo,date:today(),createdAt:new Date().toISOString(),customerId:customer?.id||null,customerName:customer?.name||"Walk-in Customer",items:cart,subtotal,discount,total,paid,due:total-paid,dueDate:$("#saleDueDate").value||"",method:$("#saleMethod").value,assistant:currentUser.name,cost:cart.reduce((a,x)=>a+x.qty*x.cost,0)};
 await put("sales",sale);for(const line of cart){const p=await get("products",line.productId),prev=Number(p.stock);p.stock=prev-line.qty;await put("products",p);await put("movements",{id:uid(),productId:p.id,productName:p.name,type:"SALE",quantity:-line.qty,previous:prev,next:p.stock,reference:invoiceNo,date:today(),user:currentUser.name})}
 if(customer){customer.balance=Number(customer.balance||0)+sale.due;customer.totalPurchases=Number(customer.totalPurchases||0)+total;customer.lastPurchaseDate=today();await put("customers",customer)}
 if(paid>0)await put("payments",{id:uid(),type:"CUSTOMER_RECEIPT",customerId:customer?.id||null,customerName:customer?.name||"Walk-in Customer",saleId:sale.id,amount:paid,date:today(),method:sale.method,reference:invoiceNo,notes:"Payment received with invoice",user:currentUser.name});
 toast("Invoice saved: "+invoiceNo);printInvoice(sale);setPage("sales")};
}
async function paymentsPage(c){const [rows,customers]=await Promise.all([all("payments"),all("customers")]);c.innerHTML=`<div class="section-head"><div><h2>Payment collection</h2><p>Record customer receipts and supplier payments.</p></div><button class="btn btn-primary" data-action="add-payment">＋ Record payment</button></div>${table(["Date","Type","Account","Method","Reference","Amount","Recorded by"],rows.slice().reverse().map(x=>`<tr><td>${fmtDate(x.date)}</td><td><span class="pill">${esc(x.type)}</span></td><td>${esc(x.customerName||x.supplierName||"—")}</td><td>${esc(x.method)}</td><td>${esc(x.reference)}</td><td><b>${money(x.amount)}</b></td><td>${esc(x.user)}</td></tr>`))}`}
