async function expensesPage(c){const rows=await all("expenses");c.innerHTML=`<div class="section-head"><div><h2>Shop expenses</h2><p>Record operating costs and cash outflows.</p></div><button class="btn btn-primary" data-action="add-expense">＋ Add expense</button></div>${table(["Date","Category","Description","Method","Amount","Recorded by"],rows.slice().reverse().map(x=>`<tr><td>${fmtDate(x.date)}</td><td>${esc(x.category)}</td><td>${esc(x.description)}</td><td>${esc(x.method)}</td><td><b>${money(x.amount)}</b></td><td>${esc(x.user)}</td></tr>`))}`}
async function reportsPage(c){const [sales,payments,expenses,products,customers]=await Promise.all(["sales","payments","expenses","products","customers"].map(all));const total=sales.reduce((a,x)=>a+x.total,0),cost=sales.reduce((a,x)=>a+x.cost,0),expense=expenses.reduce((a,x)=>a+x.amount,0),received=payments.filter(x=>x.type==="CUSTOMER_RECEIPT").reduce((a,x)=>a+x.amount,0);c.innerHTML=`<div class="section-head"><div><h2>Business reports</h2><p>Current all-time summary from locally stored transactions.</p></div><button class="btn btn-light" id="exportCSV">Export sales CSV</button></div><div class="grid stats">${stat("Sales revenue",money(total),"Saved invoices","↗")}${stat("Cost of goods sold",money(cost),"Recorded purchase cost","▤")}${stat("Estimated gross profit",money(total-cost),"Revenue minus recorded product cost","＋")}${stat("Estimated net profit",money(total-cost-expense),"Gross profit minus recorded expenses","৳")}</div><div class="grid two-col"><div class="card"><h2>Receivables & collections</h2><div class="metric-list"><div class="metric-row"><span>Customer outstanding</span><b>${money(customers.reduce((a,x)=>a+Number(x.balance||0),0))}</b></div><div class="metric-row"><span>Payments received (all time)</span><b>${money(received)}</b></div><div class="metric-row"><span>Invoices</span><b>${sales.length}</b></div></div></div><div class="card"><h2>Inventory summary</h2><div class="metric-list"><div class="metric-row"><span>Product records</span><b>${products.length}</b></div><div class="metric-row"><span>Units in stock (sum)</span><b>${products.reduce((a,x)=>a+Number(x.stock||0),0).toLocaleString()}</b></div><div class="metric-row"><span>Low stock</span><b>${products.filter(x=>Number(x.stock)<=Number(x.minStock)).length}</b></div></div></div></div><div class="note" style="margin-top:16px">Profit is an estimate based on the purchase cost recorded on each sale line. This starter does not yet implement a full double-entry accounting ledger, tax accounting, or audited financial statements.</div>`;
 $("#exportCSV").onclick=()=>downloadCSV("sales.csv",["Invoice","Date","Customer","Subtotal","Discount","Total","Paid","Due"],sales.map(x=>[x.invoiceNo,x.date,x.customerName,x.subtotal,x.discount,x.total,x.paid,x.due]))}
async function cloudPage(c){
 const state=window.cloudERP?await window.cloudERP.status():{configured:false,online:navigator.onLine};
 c.innerHTML=`<div class="grid two-col"><div class="card"><h2>Secure cloud connection</h2><p class="muted">Configure your Supabase project once on each device. The public anon key is designed for browser use; database access is protected by Row Level Security.</p><div class="form-grid" style="margin-top:14px"><div class="field full"><label>Supabase project URL</label><input class="input" id="sbUrl" placeholder="https://YOUR-PROJECT.supabase.co" value="${esc(window.cloudERP?.config()?.url||"")}"></div><div class="field full"><label>Supabase publishable / anon key</label><input class="input" id="sbKey" placeholder="sb_publishable_... or legacy anon key" value="${esc(window.cloudERP?.config()?.key||"")}"></div></div><button class="btn btn-primary" id="saveCloudConfig" style="margin-top:12px">Save connection</button><div class="note" style="margin-top:13px">Never paste a service-role key into this app. Only use the public anon/publishable key.</div></div><div class="card"><h2>Account & synchronization</h2><p class="muted" id="cloudStatus">${state.configured?(state.user?`Signed in as ${esc(state.user.email)}`:"Connection configured · sign in required"):"Not configured"}</p><div class="form-grid"><div class="field full"><label>Email</label><input class="input" id="cloudEmail" type="email" autocomplete="username"></div><div class="field full"><label>Password</label><input class="input" id="cloudPassword" type="password" autocomplete="current-password"></div></div><div class="quick-actions" style="margin-top:12px"><button class="btn btn-primary" id="cloudSignIn">Sign in</button><button class="btn btn-light" id="cloudSignUp">Create account</button><button class="btn btn-light" id="cloudSignOut">Sign out</button></div><hr style="border:0;border-top:1px solid var(--line);margin:18px 0"><div class="field"><label>Shop name (first-time owner setup)</label><input class="input" id="cloudShopName" placeholder="Your shop name"></div><div class="quick-actions" style="margin-top:10px"><button class="btn btn-primary" id="cloudCreateShop">Create new shop</button><button class="btn btn-light" id="cloudSyncNow">Sync now</button></div><p class="muted" id="syncResult" style="font-size:11px;margin-top:12px">Offline edits are saved on this device and queued for sync.</p></div></div><div class="card" style="margin-top:16px"><h2>Invite an assistant / manager</h2><p class="muted">The staff member must first create and verify an account. Then add their email here.</p><div class="toolbar" style="margin-top:12px"><input class="input search" id="staffEmail" type="email" placeholder="Staff account email"><select class="select" id="staffRole"><option value="assistant">Assistant</option><option value="manager">Manager</option></select><button class="btn btn-primary" id="addStaff">Add team member</button></div><p class="muted" style="font-size:11px">Role restrictions are enforced by the database sync API. Keep owner credentials private.</p></div><div class="note danger-note" style="margin-top:16px">Offline-first does not mean cloud login can be created offline. Each device must sign in while online at least once. Browser data is device-specific; keep regular JSON backups. Do not use public/shared computers for owner sessions.</div>`;
 const bind=(id,fn)=>{const el=$("#"+id);if(el)el.onclick=fn};
 bind("saveCloudConfig",async()=>{try{await window.cloudERP.configure($("#sbUrl").value.trim(),$("#sbKey").value.trim());toast("Cloud configuration saved.");cloudPage($("#content"))}catch(e){toast(e.message)}});
 bind("cloudSignIn",async()=>{try{await window.cloudERP.signIn($("#cloudEmail").value,$("#cloudPassword").value);toast("Signed in.");cloudPage($("#content"))}catch(e){toast(e.message)}});
 bind("cloudSignUp",async()=>{try{const r=await window.cloudERP.signUp($("#cloudEmail").value,$("#cloudPassword").value);toast(r.message||"Account created. Check your email if verification is enabled.")}catch(e){toast(e.message)}});
 bind("cloudSignOut",async()=>{try{await window.cloudERP.signOut();toast("Signed out.");cloudPage($("#content"))}catch(e){toast(e.message)}});
 bind("cloudCreateShop",async()=>{try{await window.cloudERP.createShop($("#cloudShopName").value.trim());toast("Shop created and local data queued for upload.");const r=await window.cloudERP.sync();$("#syncResult").textContent=r.message;cloudPage($("#content"))}catch(e){toast(e.message)}});
 bind("cloudSyncNow",async()=>{try{const r=await window.cloudERP.sync();$("#syncResult").textContent=r.message;toast("Sync completed.")}catch(e){toast(e.message)}});
 bind("addStaff",async()=>{try{await window.cloudERP.addMember($("#staffEmail").value.trim(),$("#staffRole").value);toast("Team member added.")}catch(e){toast(e.message)}});
}
async function settingsPage(c){const s=await get("settings","shop")||{};c.innerHTML=`<div class="grid two-col"><div class="card"><h2>Shop settings</h2><p class="muted">Customize invoice and stock settings.</p><div class="form-grid" style="margin-top:16px"><div class="field full"><label>Shop name</label><input class="input" id="shopName" value="${esc(s.shopName||"Gill Spray Centre")}"></div><div class="field"><label>Phone (general)</label><input class="input" id="shopPhone" value="${esc(s.phone||"")}"></div><div class="field"><label>Contact 1 name</label><input class="input" id="contact1Name" value="${esc(s.contact1Name||"Attaullah Gill")}"></div><div class="field"><label>Contact 1 mobile</label><input class="input" id="contact1Phone" value="${esc(s.contact1Phone||"03007521693")}"></div><div class="field"><label>Contact 2 name</label><input class="input" id="contact2Name" value="${esc(s.contact2Name||"Luqman Gill")}"></div><div class="field"><label>Contact 2 mobile</label><input class="input" id="contact2Phone" value="${esc(s.contact2Phone||"03006981118")}"></div><div class="field"><label>Low-stock default</label><input class="input" type="number" id="lowStock" value="${s.lowStock??5}"></div><div class="field full"><label>Shop address</label><textarea class="input" id="shopAddress">${esc(s.address||"Qazi Wala Road Adda Pull Murad, Tehsil Chishtian")}</textarea></div></div><button class="btn btn-primary" id="saveSettings" style="margin-top:14px">Save settings</button></div><div class="card"><h2>Data backup & restore</h2><p class="muted">Your records are stored locally in this browser.</p><div class="note danger-note">Important: browser storage is not a substitute for a backup. If you clear browser data, lose the device, or reset the browser profile, records may be lost.</div><div class="quick-actions" style="margin-top:16px"><button class="btn btn-primary" id="backupBtn">⇧ Download full backup</button><label class="btn btn-light">⇩ Restore backup<input type="file" id="restoreFile" accept="application/json" hidden></label></div><p class="muted" style="font-size:11px;margin-top:14px">Keep at least two backup copies in separate safe locations. Restoring replaces matching local tables.</p><hr style="border:0;border-top:1px solid var(--line);margin:20px 0"><h2>Data portability</h2><p class="muted">Cloud Sync & Team connects devices through your Supabase project. Keep regular JSON backups as an independent safety copy.</p></div></div>`;
 $("#saveSettings").onclick=async()=>{await put("settings",{id:"shop",shopName:$("#shopName").value,phone:$("#shopPhone").value,contact1Name:$("#contact1Name").value,contact1Phone:$("#contact1Phone").value,contact2Name:$("#contact2Name").value,contact2Phone:$("#contact2Phone").value,address:$("#shopAddress").value,lowStock:Number($("#lowStock").value)||5,currency:"PKR"});toast("Settings saved.")};$("#backupBtn").onclick=backup;$("#restoreFile").onchange=restore}
function modal(title,body,saveLabel,saveFn){const root=$("#modalRoot");root.innerHTML=`<div class="modal-backdrop"><div class="modal"><h2>${title}</h2>${body}<div class="modal-actions"><button class="btn btn-light" id="modalCancel">Cancel</button><button class="btn btn-primary" id="modalSave">${saveLabel||"Save"}</button></div></div></div>`;$("#modalCancel").onclick=()=>root.innerHTML="";$("#modalSave").onclick=async()=>{try{await saveFn();root.innerHTML="";await render()}catch(e){toast(e.message||"Could not save record.")}}}
function field(label,id,type="text",value="",extra=""){return `<div class="field"><label>${label}</label><input class="input" id="${id}" type="${type}" value="${esc(value)}" ${extra}></div>`}
async function addCompany(x={}){modal(x.id?"Edit company":"Add company",`<div class="form-grid">${field("Company name *","fName","text",x.name||"")}${field("Representative","fRep","text",x.representative||"")}${field("Phone","fPhone","text",x.phone||"")}${field("Address","fAddress","text",x.address||"")}</div>`,"Save company",async()=>{const name=$("#fName").value.trim();if(!name)throw Error("Company name is required.");await put("companies",{...x,id:x.id||uid(),name,representative:$("#fRep").value,phone:$("#fPhone").value,address:$("#fAddress").value})})}
async function addProduct(x={}){const companies=await all("companies");modal(x.id?"Edit product":"Add product",`<div class="form-grid"><div class="field full"><label>Product name *</label><input class="input" id="fName" value="${esc(x.name||"")}"></div><div class="field"><label>Company</label><select class="select" id="fCompany">${companies.map(a=>`<option value="${a.id}" ${a.id===x.companyId?"selected":""}>${esc(a.name)}</option>`).join("")}</select></div><div class="field"><label>Category</label><select class="select" id="fCategory">${["Insecticides","Herbicides","Fungicides","Fertilizers","Micronutrients","Seeds","Growth Regulators","Other"].map(a=>`<option ${a===x.category?"selected":""}>${a}</option>`).join("")}</select></div>${field("Brand","fBrand","text",x.brand||"")}${field("SKU / Barcode","fSku","text",x.sku||"")}${field("Packing size","fPack","text",x.packSize||"")}${field("Unit","fUnit","text",x.unit||"bottle")}${field("Purchase price","fPurchase","number",x.purchasePrice||0,'step=".01"')}${field("Retail price","fRetail","number",x.retailPrice||0,'step=".01"')}${field("Wholesale price","fWholesale","number",x.wholesalePrice||0,'step=".01"')}${field("Current stock","fStock","number",x.stock||0,'step=".01"')}${field("Minimum stock alert","fMin","number",x.minStock||0,'step=".01"')}${field("Batch number","fBatch","text",x.batch||"")}${field("Expiry date","fExpiry","date",x.expiryDate||"")}</div><p class="muted" style="font-size:11px">For multiple pack sizes, create one product record per pack size. Opening stock is recorded as an opening movement.</p>`,"Save product",async()=>{const name=$("#fName").value.trim();if(!name)throw Error("Product name is required.");const generatedCode=($("#fSku").value.trim()||x.barcode||x.sku||("GSC"+Date.now().toString().slice(-9))).toUpperCase().replace(/[^0-9A-Z. $/+%-]/g,"-");const p={...x,id:x.id||uid(),name,companyId:$("#fCompany").value,category:$("#fCategory").value,brand:$("#fBrand").value,sku:generatedCode,barcode:generatedCode,packSize:$("#fPack").value,unit:$("#fUnit").value,purchasePrice:Number($("#fPurchase").value),retailPrice:Number($("#fRetail").value),wholesalePrice:Number($("#fWholesale").value),stock:Number($("#fStock").value),minStock:Number($("#fMin").value),batch:$("#fBatch").value,expiryDate:$("#fExpiry").value};await put("products",p);if(!x.id&&p.stock>0)await put("movements",{id:uid(),productId:p.id,productName:p.name,type:"OPENING",quantity:p.stock,previous:0,next:p.stock,reference:"Opening stock",date:today(),user:currentUser.name})})}
async function addCustomer(x={}){modal(x.id?"Edit customer":"Register customer",`<div class="form-grid">${field("Customer name *","fName","text",x.name||"")}${field("Father's name","fFather","text",x.fatherName||"")}${field("Mobile number","fPhone","tel",x.phone||"")}${field("Village / town","fVillage","text",x.village||"")}${field("Address","fAddress","text",x.address||"")}${field("Customer type","fType","text",x.type||"Farmer")}${field("Credit limit (PKR)","fLimit","number",x.creditLimit||0)}${field("Opening balance (PKR)","fBalance","number",x.balance||0)}</div>`,"Save customer",async()=>{const name=$("#fName").value.trim();if(!name)throw Error("Customer name is required.");const obj={...x,id:x.id||uid(),name,fatherName:$("#fFather").value,phone:$("#fPhone").value,village:$("#fVillage").value,address:$("#fAddress").value,type:$("#fType").value,creditLimit:Number($("#fLimit").value),balance:Number($("#fBalance").value),accountNo:x.accountNo||"CUS-"+String(Date.now()).slice(-6)};await put("customers",obj)})}
async function addPayment(){const customers=await all("customers");modal("Record customer payment",`<div class="form-grid"><div class="field full"><label>Customer *</label><select class="select" id="fCustomer">${customers.map(x=>`<option value="${x.id}">${esc(x.name)} · Due ${money(x.balance)}</option>`).join("")}</select></div>${field("Amount received *","fAmount","number",0,'min="0.01" step=".01"') }<div class="field"><label>Payment method</label><select class="select" id="fMethod"><option>Cash</option><option>Bank transfer</option><option>JazzCash</option><option>Easypaisa</option><option>Cheque</option><option>Other</option></select></div>${field("Date","fDate","date",today())}${field("Reference number","fRef")}${field("Notes","fNotes")}</div>`,"Save payment",async()=>{const customer=await get("customers",$("#fCustomer").value),amount=Number($("#fAmount").value);if(!customer||amount<=0)throw Error("Choose customer and valid amount.");customer.balance=Number(customer.balance||0)-amount;await put("customers",customer);await put("payments",{id:uid(),type:"CUSTOMER_RECEIPT",customerId:customer.id,customerName:customer.name,amount,date:$("#fDate").value,method:$("#fMethod").value,reference:$("#fRef").value,notes:$("#fNotes").value,user:currentUser.name});})}
async function addPurchase(){const [products,suppliers]=await Promise.all([all("products"),all("suppliers")]);modal("Add purchase",`<div class="form-grid"><div class="field full"><label>Scan product barcode / SKU</label><div class="scan-row"><input class="input" id="fPurchaseBarcode" placeholder="Scan with handheld scanner or type code"><button class="btn btn-light" id="purchaseCameraScan">▣ Camera</button></div></div><div class="field full"><label>Product *</label><select class="select" id="fProduct">${products.map(x=>`<option value="${x.id}">${esc(x.name)} · ${esc(x.packSize)}</option>`).join("")}</select></div><div class="field"><label>Supplier name</label><input class="input" id="fSupplier" list="supplierList"><datalist id="supplierList">${suppliers.map(x=>`<option value="${esc(x.name)}">`).join("")}</datalist></div>${field("Quantity *","fQty","number",1,'min=".01" step=".01"')}${field("Purchase rate *","fRate","number",0,'min="0" step=".01"')}${field("Amount paid","fPaid","number",0,'min="0" step=".01"')}${field("Purchase date","fDate","date",today())}</div>`,"Save purchase",async()=>{const p=await get("products",$("#fProduct").value),qty=Number($("#fQty").value),rate=Number($("#fRate").value),paid=Number($("#fPaid").value);if(!p||qty<=0||rate<0)throw Error("Enter valid purchase details.");const total=qty*rate;if(paid>total)throw Error("Paid amount cannot exceed purchase total.");const supplierName=$("#fSupplier").value.trim();let sup=suppliers.find(x=>x.name.toLowerCase()===supplierName.toLowerCase());if(supplierName&&!sup){sup={id:uid(),name:supplierName,balance:0};await put("suppliers",sup)}const prev=Number(p.stock);p.stock=prev+qty;await put("products",p);const obj={id:uid(),purchaseNo:"PUR-"+String(Date.now()).slice(-7),productId:p.id,productName:p.name,supplierId:sup?.id||null,supplierName,qty,rate,total,paid,due:total-paid,date:$("#fDate").value};await put("purchases",obj);await put("movements",{id:uid(),productId:p.id,productName:p.name,type:"PURCHASE",quantity:qty,previous:prev,next:p.stock,reference:obj.purchaseNo,date:obj.date,user:currentUser.name});if(sup){sup.balance=Number(sup.balance||0)+obj.due;await put("suppliers",sup)}});$("#purchaseCameraScan").onclick=()=>startBarcodeCamera("fPurchaseBarcode");$("#fPurchaseBarcode").onkeydown=e=>{if(e.key!=="Enter")return;e.preventDefault();const code=e.currentTarget.value.trim().toLowerCase();const found=products.find(p=>String(p.sku||"").toLowerCase()===code||String(p.barcode||"").toLowerCase()===code);if(!found)return toast("No product found for this barcode.");$("#fProduct").value=found.id;};}
async function addExpense(){modal("Add shop expense",`<div class="form-grid"><div class="field"><label>Category</label><select class="select" id="fCategory">${["Salaries","Shop rent","Electricity","Transportation","Fuel","Maintenance","Other"].map(x=>`<option>${x}</option>`).join("")}</select></div>${field("Amount *","fAmount","number",0,'min=".01" step=".01"')}${field("Description","fDesc")}${field("Date","fDate","date",today())}<div class="field"><label>Payment method</label><select class="select" id="fMethod"><option>Cash</option><option>Bank transfer</option><option>Other</option></select></div></div>`,"Save expense",async()=>{const amount=Number($("#fAmount").value);if(amount<=0)throw Error("Enter a valid amount.");await put("expenses",{id:uid(),category:$("#fCategory").value,amount,description:$("#fDesc").value,date:$("#fDate").value,method:$("#fMethod").value,user:currentUser.name})})}
async function ledger(id){const customer=await get("customers",id),sales=await all("sales"),payments=await all("payments");const entries=[...sales.filter(x=>x.customerId===id).map(x=>({date:x.date,type:"Sale · "+x.invoiceNo,debit:Number(x.total??x.due??0),credit:0})),...payments.filter(x=>x.customerId===id).map(x=>({date:x.date,type:"Payment · "+(x.reference||""),debit:0,credit:x.amount}))].sort((a,b)=>a.date.localeCompare(b.date));let bal=0;const rows=entries.map(x=>{bal+=x.debit-x.credit;return `<tr><td>${fmtDate(x.date)}</td><td>${esc(x.type)}</td><td>${money(x.debit)}</td><td>${money(x.credit)}</td><td><b>${money(bal)}</b></td></tr>`});modal("Customer ledger · "+esc(customer.name),`<div class="note">Mobile: ${esc(customer.phone)} · Village: ${esc(customer.village)} · Current balance: <b>${money(customer.balance)}</b></div><div style="margin-top:14px">${table(["Date","Transaction","Debit","Credit","Running balance"],rows,"No ledger transactions.")}</div>`,"Close",async()=>{})}
async function customerProductHistory(id){
 const customer=await get("customers",id);if(!customer)return;
 const sales=(await all("sales")).filter(s=>s.customerId===id).sort((a,b)=>(b.date||"").localeCompare(a.date||""));
 const grouped=new Map();
 for(const sale of sales)for(const item of (sale.items||[])){
  const key=item.productId||item.name;const row=grouped.get(key)||{name:item.name||"Unknown product",packSize:item.packSize||"",qty:0,amount:0,count:0,lastDate:sale.date||"",invoices:[]};
  row.qty+=Number(item.qty||0);row.amount+=Number(item.qty||0)*Number(item.price||0);row.count++;if(!row.invoices.includes(sale.invoiceNo))row.invoices.push(sale.invoiceNo);if((sale.date||"")>row.lastDate)row.lastDate=sale.date||"";grouped.set(key,row);
 }
 const summary=[...grouped.values()].sort((a,b)=>b.amount-a.amount);
 const detail=sales.flatMap(s=>(s.items||[]).map(i=>`<tr><td>${fmtDate(s.date)}</td><td>${esc(s.invoiceNo)}</td><td>${esc(i.name)} ${esc(i.packSize||"")}</td><td>${Number(i.qty||0)}</td><td>${money(i.price)}</td><td>${money(Number(i.qty||0)*Number(i.price||0))}</td></tr>`));
 modal("Purchase history · "+esc(customer.name),`<div class="note">Customer: <b>${esc(customer.name)}</b> · Account: ${esc(customer.accountNo||"—")} · Total invoices: <b>${sales.length}</b> · Current outstanding: <b>${money(customer.balance)}</b></div><h3 style="margin-top:18px">Product summary</h3>${table(["Product","Total quantity","Purchase lines","Total amount","Last purchase"],summary.map(x=>`<tr><td><b>${esc(x.name)}</b><div class="muted">${esc(x.packSize)}</div></td><td>${x.qty}</td><td>${x.count}</td><td>${money(x.amount)}</td><td>${fmtDate(x.lastDate)}</td></tr>`),"No product purchases recorded for this customer.")}<h3 style="margin-top:18px">Invoice-wise product details</h3>${table(["Date","Invoice","Product","Qty","Rate","Amount"],detail,"No invoice items found.")}`,"Close",async()=>{});
}
async function productBuyers(id){
 const product=await get("products",id);if(!product)return;
 const customers=await all("customers"),sales=await all("sales"),buyers=new Map();
 for(const sale of sales)for(const item of (sale.items||[]))if(item.productId===id||(item.name===product.name&&item.packSize===product.packSize)){
  const key=sale.customerId||"walkin";const row=buyers.get(key)||{name:sale.customerName||"Walk-in Customer",qty:0,amount:0,lastDate:"",invoices:0};row.qty+=Number(item.qty||0);row.amount+=Number(item.qty||0)*Number(item.price||0);row.lastDate=(sale.date||"")>row.lastDate?(sale.date||""):row.lastDate;row.invoices++;buyers.set(key,row);
 }
 const rows=[...buyers.entries()].map(([id,x])=>{const c=customers.find(v=>v.id===id);return `<tr><td><b>${esc(x.name)}</b><div class="muted">${esc(c?.phone||"")}</div></td><td>${x.qty}</td><td>${money(x.amount)}</td><td>${x.invoices}</td><td>${fmtDate(x.lastDate)}</td><td>${money(c?.balance||0)}</td></tr>`});
 modal("Customers who bought · "+esc(product.name),`<div class="note">Product: <b>${esc(product.name)}</b> · Pack: ${esc(product.packSize||"")} ${esc(product.unit||"")}</div>${table(["Customer","Total quantity","Total amount","Purchase lines","Last purchase","Outstanding"],rows,"No customer purchases found for this product.")}`,"Close",async()=>{});
}
async function stockAdjust(id){const p=await get("products",id);modal("Adjust stock · "+esc(p.name),`<div class="form-grid">${field("Adjustment quantity (+/-)","fQty","number",0,'step=".01"')}${field("Reason","fReason")}</div><p class="muted">Use a positive number to add stock and a negative number to reduce it.</p>`,"Save adjustment",async()=>{const qty=Number($("#fQty").value),prev=Number(p.stock),next=prev+qty;if(!qty||next<0)throw Error("Invalid adjustment: stock cannot be negative.");p.stock=next;await put("products",p);await put("movements",{id:uid(),productId:p.id,productName:p.name,type:"ADJUSTMENT",quantity:qty,previous:prev,next,reason:$("#fReason").value,reference:"Manual adjustment",date:today(),user:currentUser.name})})}
async function deleteCompany(id){const products=await all("products");if(products.some(p=>p.companyId===id))return toast("Cannot delete: company has linked products. Mark it inactive or remove links first.");if(confirm("Delete this company?")){await del("companies",id);render()}}
async function printInvoice(s){const settings=await get("settings","shop")||{};const address=settings.address||"Qazi Wala Road Adda Pull Murad, Tehsil Chishtian";const contacts=[{name:settings.contact1Name||"Attaullah Gill",phone:settings.contact1Phone||"03007521693"},{name:settings.contact2Name||"Luqman Gill",phone:settings.contact2Phone||"03006981118"}];const invoiceUrl=location.origin+location.pathname+"?invoice="+encodeURIComponent(s.invoiceNo);const qr=qrSvg(invoiceUrl,132);const w=window.open("","_blank","width=820,height=900");if(!w){toast("Allow pop-ups to print invoice.");return}w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${esc(s.invoiceNo)}</title><style>@page{size:A4;margin:12mm}*{box-sizing:border-box}body{font:13px Arial,sans-serif;color:#183329;margin:0;background:#fff}.sheet{max-width:780px;margin:20px auto;border:1px solid #dce8e0;border-radius:16px;overflow:hidden}.head{background:#174b39;color:white;padding:25px 30px;display:flex;justify-content:space-between;gap:20px;align-items:center}.brand{font-size:25px;font-weight:800;letter-spacing:.3px}.tag{font-size:11px;opacity:.8;margin-top:5px}.inv{background:#e8f3ed;color:#174b39;padding:13px 17px;border-radius:12px;text-align:right}.inv b{display:block;font-size:17px}.body{padding:24px 30px}.address{font-size:12px;color:#52665b;margin:0 0 17px}.meta{display:flex;justify-content:space-between;gap:20px;border-top:1px solid #e5eee8;border-bottom:1px solid #e5eee8;padding:13px 0;margin-bottom:18px}.meta strong{display:block;margin-bottom:4px}.meta span{color:#61736a}.items{width:100%;border-collapse:collapse}.items th{background:#edf5ef;color:#315d48;text-align:left;font-size:11px;padding:11px}.items td{padding:12px 11px;border-bottom:1px solid #e8eee9}.r{text-align:right}.summary{margin:18px 0 0 auto;width:280px}.summary div{display:flex;justify-content:space-between;padding:6px 0}.summary .grand{font-size:17px;font-weight:bold;color:#174b39;border-top:2px solid #174b39;margin-top:6px;padding-top:10px}.bottom{display:flex;justify-content:space-between;align-items:end;gap:25px;margin-top:25px;padding-top:18px;border-top:1px dashed #cbd9d0}.qr{text-align:center;font-size:10px;color:#62736a}.qr svg{display:block;margin:auto}.contacts{display:grid;gap:7px;color:#41594c;font-size:12px}.contacts b{color:#173f32}.thanks{text-align:center;background:#f3f8f4;color:#42634f;padding:14px;font-weight:bold;margin-top:20px}.foot{font-size:10px;color:#718078;text-align:center;padding:12px}@media print{body{margin:0}.sheet{margin:0 auto;border:0;border-radius:0;max-width:none}.head{-webkit-print-color-adjust:exact;print-color-adjust:exact}.inv,.items th,.thanks{print-color-adjust:exact;-webkit-print-color-adjust:exact}}</style></head><body><div class="sheet"><div class="head"><div><div class="brand">🌿 ${esc(settings.shopName||"Gill Spray Centre")}</div><div class="tag">GSC · SALES INVOICE</div></div><div class="inv"><span>INVOICE</span><b>${esc(s.invoiceNo)}</b><small>${fmtDate(s.date)}</small></div></div><div class="body"><p class="address">${esc(address)}</p><div class="meta"><div><strong>Bill To</strong><span>${esc(s.customerName)}</span></div><div style="text-align:right"><strong>Invoice Date</strong><span>${fmtDate(s.date)}</span></div></div><table class="items"><thead><tr><th>Product / Description</th><th>Qty</th><th>Rate</th><th class="r">Amount</th></tr></thead><tbody>${(s.items||[]).map(x=>`<tr><td><b>${esc(x.name)}</b><br><small>${esc(x.packSize||"")} ${esc(x.unit||"")}</small></td><td>${x.qty}</td><td>${money(x.price)}</td><td class="r">${money(x.qty*x.price)}</td></tr>`).join("")}</tbody></table><div class="summary"><div><span>Subtotal</span><b>${money(s.subtotal)}</b></div><div><span>Discount</span><b>${money(s.discount)}</b></div><div class="grand"><span>Net Total</span><b>${money(s.total)}</b></div><div><span>Amount Received</span><b>${money(s.paid)}</b></div><div><span>Remaining Balance</span><b>${money(s.due)}</b></div></div><div class="bottom"><div class="contacts"><div><b>${esc(contacts[0].name)}</b> · ${esc(contacts[0].phone)}</div><div><b>${esc(contacts[1].name)}</b> · ${esc(contacts[1].phone)}</div></div><div class="qr">${qr}<div>Scan to view this invoice</div></div></div><div class="thanks">Thank you for choosing Gill Spray Centre!</div></div><div class="foot">Please keep this invoice for your records.</div></div><script>window.onload=()=>window.print()</script></body></html>`);w.document.close()}
async function viewInvoice(invoiceNo){const s=(await all("sales")).find(x=>x.invoiceNo===invoiceNo);if(!s)return toast("Invoice not found on this device. Sync and try again.");const url=location.origin+location.pathname+"?invoice="+encodeURIComponent(s.invoiceNo);modal("Invoice details · "+esc(s.invoiceNo),`<div class="invoice-detail"><div class="note">Customer: <b>${esc(s.customerName)}</b> · Date: ${fmtDate(s.date)}</div>${table(["Product","Qty","Rate","Amount"],(s.items||[]).map(x=>`<tr><td>${esc(x.name)} ${esc(x.packSize||"")}</td><td>${x.qty}</td><td>${money(x.price)}</td><td>${money(x.qty*x.price)}</td></tr>`))}<div class="invoice-summary"><p>Subtotal: <b>${money(s.subtotal)}</b></p><p>Discount: <b>${money(s.discount)}</b></p><p>Total: <b>${money(s.total)}</b></p><p>Paid: <b>${money(s.paid)}</b></p><p>Due: <b>${money(s.due)}</b></p></div><div class="qr-preview">${qrSvg(url,150)}<small>Scan to open this invoice</small></div><button class="btn btn-light" id="printInvoiceDetail">Print invoice</button></div>` ,"Close",async()=>{});$('#printInvoiceDetail').onclick=()=>printInvoice(s)}
async function showBarcode(id){const p=await get("products",id);if(!p)return;const code=p.barcode||p.sku||"";modal("Product barcode · "+esc(p.name),`<div class="barcode-preview">${barcodeSvg(code)}<p><b>${esc(p.name)}</b><br><span class="muted">${esc(code)}</span></p><button class="btn btn-light" id="printBarcodeLabel">Print barcode label</button></div>`,"Close",async()=>{});$('#printBarcodeLabel').onclick=()=>{const w=window.open("","_blank","width=420,height=260");if(!w)return toast("Allow pop-ups to print label.");w.document.write(`<html><body style="font:13px Arial;text-align:center;padding:20px"><b>${esc(p.name)}</b><div>${barcodeSvg(code)}</div><script>window.onload=()=>window.print()</script></body></html>`);w.document.close()}}
async function maybeOpenInvoiceFromQuery(){const invoice=new URLSearchParams(location.search).get('invoice');if(!invoice||window.__invoiceQueryHandled)return;const s=(await all('sales')).find(x=>x.invoiceNo===invoice);if(s){window.__invoiceQueryHandled=true;setPage('sales');viewInvoice(invoice)}}

async function backup(){const data={app:"Pesticide Shop ERP",version:1,exportedAt:new Date().toISOString(),tables:{}};for(const t of TABLES)data.tables[t]=await all(t);const blob=new Blob([JSON.stringify(data,null,2)],{type:"application/json"});downloadBlob(blob,"pesticide-shop-backup-"+today()+".json");toast("Backup downloaded.")}
function downloadBlob(blob,name){const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}
function downloadCSV(name,headers,rows){const csv=[headers,...rows].map(r=>r.map(v=>'"'+String(v??"").replaceAll('"','""')+'"').join(",")).join("\n");downloadBlob(new Blob(["\ufeff"+csv],{type:"text/csv;charset=utf-8"}),name)}
async function restore(e){const f=e.target.files[0];if(!f)return;try{const data=JSON.parse(await f.text());if(!data.tables)throw Error("Invalid backup file.");if(!confirm("Restore will replace local records in included tables. Continue?"))return;for(const t of TABLES){if(!data.tables[t])continue;await new Promise((res,rej)=>{const tx=db.transaction(t,"readwrite"),store=tx.objectStore(t);store.clear();data.tables[t].forEach(x=>store.put(x));tx.oncomplete=res;tx.onerror=()=>rej(tx.error)})}toast("Backup restored.");render()}catch(err){toast(err.message||"Restore failed.")}}
document.addEventListener("click",async e=>{const b=e.target.closest("button");if(!b)return;if(b.dataset.page)setPage(b.dataset.page);if(b.dataset.go)setPage(b.dataset.go);
 const a=b.dataset.action;if(a==="add-company")addCompany();if(a==="add-product")addProduct();if(a==="add-customer")addCustomer();if(a==="add-payment")addPayment();if(a==="add-purchase")addPurchase();if(a==="add-expense")addExpense();
 if(b.dataset.edit){const type=b.dataset.edit,id=b.dataset.id,obj=await get(type==="company"?"companies":type==="product"?"products":"customers",id);if(type==="company")addCompany(obj);if(type==="product")addProduct(obj);if(type==="customer")addCustomer(obj)}
 if(b.dataset.delete==="company")deleteCompany(b.dataset.id);if(b.dataset.barcode)showBarcode(b.dataset.barcode);if(b.dataset.invoice)viewInvoice(b.dataset.invoice);if(b.dataset.ledger)ledger(b.dataset.ledger);if(b.dataset.customerHistory)customerProductHistory(b.dataset.customerHistory);if(b.dataset.buyers)productBuyers(b.dataset.buyers);if(b.dataset.stock)stockAdjust(b.dataset.stock);
 if(b.dataset.cartremove!==undefined){window.saleCart.splice(Number(b.dataset.cartremove),1);$("#saleCart").innerHTML="";$("#saleTotal").textContent="Total: "+money(window.saleCart.reduce((a,x)=>a+x.qty*x.price,0)-Number($("#saleDiscount").value||0));renderCartAfterRemove()}
 if(b.id==="quickBackup")backup();if(b.id==="menuToggle")document.querySelector(".sidebar").classList.toggle("open");
});
function renderCartAfterRemove(){const cart=window.saleCart;$("#saleCart").innerHTML=cart.length?table(["Product","Qty","Rate","Amount",""],cart.map((x,i)=>`<tr><td>${esc(x.name)}</td><td>${x.qty}</td><td>${money(x.price)}</td><td>${money(x.qty*x.price)}</td><td><button class="btn btn-danger btn-small" data-cartremove="${i}">×</button></td></tr>`)):`<div class="empty">No products added yet.</div>`}
document.addEventListener("input",e=>{if(e.target.id==="productSearch"){window.productQuery=e.target.value;productsPage($("#content"))}if(e.target.id==="customerSearch"){window.customerQuery=e.target.value;customersPage($("#content"))}});
document.addEventListener("change",e=>{if(e.target.id==="companyFilter"){const id=e.target.value;productsPage($("#content")).then(()=>{if(id)$("#companyFilter").value=id})}});
async function init(){db=await openDB();window.erpDB=()=>db;await seed();$("#todayLabel").textContent=new Date().toLocaleDateString("en-PK",{weekday:"short",day:"numeric",month:"short",year:"numeric"});if("serviceWorker"in navigator)navigator.serviceWorker.register("./sw.js").catch(()=>{});document.querySelectorAll(".nav-item").forEach(b=>b.addEventListener("click",()=>setPage(b.dataset.page)));await render();setTimeout(maybeOpenInvoiceFromQuery,700);window.addEventListener("erp:cloud-synced",()=>maybeOpenInvoiceFromQuery())}
init().catch(e=>{console.error(e);$("#content").innerHTML=`<div class="card"><h2>Application could not start</h2><p>${esc(e.message)}</p><p class="muted">Run this app through localhost or HTTPS. Browser security blocks service workers and some storage features from file:// URLs.</p></div>`});